def rob_colored_houses(nums,colors):
    skip=0;take=nums[0]
    for i in range(1,len(nums)):
        best=max(skip,take)
        if colors[i-1]==colors[i]:skip,take=best,skip+nums[i]
        else:skip,take=best,best+nums[i]
    return max(skip,take)

